void siftDown(List<int> a, int i, int n) {
  while (true) {
    final l = 2 * i + 1, r = l + 1;
    var m = i;
    if (l < n && a[l] < a[m]) m = l;
    if (r < n && a[r] < a[m]) m = r;
    if (m == i) return;
    final t = a[i];
    a[i] = a[m];
    a[m] = t;
    i = m;
  }
}

